  Dt = `Νέα για μέλη ομάδας και άτομα που ακολουθούν τον επιμελητή`,
  Ot = `Συμβάν εκπτώσεων`,
  kt = `Δημιουργήστε μια σελίδα υποδοχής για τα παιχνίδια εντός της αρχικής δημιουργού σας.`,
  At = `Αυτές οι αναρτήσεις θα εμφανίζονται στην αρχική σελίδα της ομάδας και στα προσωπικά Κέντρα Νέων των ακολούθων σου.`,
  jt = `Εντυπώσεις: %1$s, Αναγνώσεις: %2$s`,
  Mt = `Εντυπώσεις: %1$s`,
  Nt = `Αναγνώσεις: %1$s`,
  Pt = `Το widget Πρόγραμμα Συμβάντων επιτρέπει στη σελίδα προσφορών να ενσωματώσει έναν περιηγητή επερχόμενων συμβάντων. Παρέχει επιπλέον ορατότητα στα παιχνίδια που παρουσιάζονται στη σελίδα προσφορών και ανταμείβει την αλληλεπίδραση με το κοινό Steam κατά τη διάρκεια των προσφορών δημιουργώντας συμβάντα ανά συγκεκριμένο παιχνίδι. Για παράδειγμα, η μετάδοση και οι συνομιλίες είναι τρόποι για να αλληλεπιδράσει ο δημιουργός με το κοινό Steam του.`,
  Ft = `Χρειάζεται να επιλέξετε έναν ή περισσότερους τύπους συμβάντων που θα επιτρέπεται να εμφανίζονται σε αυτό το πρόγραμμα.`,
  It = `Επιλέξτε ένα εύρος ημερομηνιών για αυτό το πρόγραμμα. Αυτό μπορεί να είναι το ίδιο με το συμβάν ή μπορεί να είναι διαφορετικό αν αυτό το συμβάν ανακοινώνει ένα μελλοντικό πρόγραμμα.`,
  Lt = `Από προεπιλογή, αυτή η σελίδα προσφορών θα έχει ένα %1$s που θα είναι η πηγή των συμβάντων. Αυτό θα είναι ορατό στους διαχειριστές των προσφορών αμέσως και σε όλους μόλις αυτή η σελίδα προσφορών είναι ορατή.`,
  Rt = `Κέντρο νέων`,
