  Ut = `Ορισμός σε ώρα έναρξης συμβάντος`,
  Wt = `Ορισμός σε ώρα λήξης συμβάντος`,
  Gt = `Συμβάντα που περιλαμβάνονται:`,
  Kt = `Να επιτρέπεται η εμφάνιση όλων των συμβάντων που πληρούν τις προϋποθέσεις, από τις επιλεγμένες εφαρμογές στο πρόγραμμα.`,
  qt = `Στο πρόγραμμα θα καταχωρίζονται πάντα όσα συμβάντα πληρούν τις προϋποθέσεις από τη βασική ομάδα και όλα τα συμβάντα από μια σειρά. Με την επιλογή αυτού του πλαισίου, κάθε εφαρμογή που είναι επιλεγμένη, θα εμφανίζει επίσης στο πρόγραμμα όσα συμβάντα της πληρούν τις προϋποθέσεις. Αν το πλαίσιο δεν επιλεγεί, περιορίζεστε σε συμβάντα που σχετίζονται με τη διοργανώτρια ομάδα Κοινότητας ή σε συμβάντα που είναι καταχωρισμένα στη σειρά.`,
