  ln = `Οι χρήστες Steam με απευθείας σύνδεσμο μπορούν να δουν αυτό το συμβάν. Η ορατότητα αυτού του συμβάντος δεν μπορεί να ανακληθεί, μπορείτε μόνο να διαγράψετε αυτό το συμβάν αν χρειάζεται να το κρύψετε.`,
