  xn = `URL δημόσια ορατού συμβάντος:`,
  Sn = `Γλώσσα`,
  Cn = `Επιλέξτε μια γλώσσα από το αναπτυσσόμενο μενού για να δείτε και να επεξεργαστείτε πεδία κειμένου για εκείνη τη συγκεκριμένη γλώσσα. Ή χρησιμοποιήστε την επιλογή εξαγωγής/εισαγωγής για να ορίσετε πολλές γλώσσες με μιας.`,
  wn = `Δεν επιλέχθηκε`,
  Tn = `Απαιτείται ο ορισμός ενός εξατομικευμένου URL σελίδας προσφορών, για να μπορείτε να δημοσιεύσετε μια σελίδα προσφορών. Το εξατομικευμένο URL χρησιμοποιείται για τη δημιουργία του URL της προσφοράς, ώστε να έχουν πρόσβαση οι πελάτες.`,
