  Qn = `Οι αρχικές σελίδες δημιουργού v2 παρέχουν έναν ευέλικτο τρόπο προσαρμογής της σελίδας εκδότη, δημιουργού παιχνιδιού ή σειράς.`,
  $n = `Αυτή η σελίδα δεν είναι ορατή. Δημοσιεύστε την πρώτα και, στη συνέχεια, μπορείτε να την ορίσετε ως την τρέχουσα αρχική σελίδα δημιουργού σας.`,
  er = `Αυτή η σελίδα <1>δεν είναι</1> η τρέχουσα αρχική σελίδα δημιουργού σας. Χρησιμοποιήστε τον <2>πίνακα ελέγχου αρχικής σελίδας δημιουργού</2> για να την ενεργοποιήσετε.`,
  tr = `Αυτή η σελίδα είναι η τρέχουσα αρχική σελίδα δημιουργού σας. Μπορείτε να τη διαχειριστείτε στον <1>πίνακα ελέγχου αρχικής σελίδας δημιουργού</1>.`,
  nr = `Άβαταρ`,
  rr = `Επεξεργασία: <1>Εργαλείο επεξεργασίας αρχικής σελίδας δημιουργού</1>`,
  ir = `Σλόγκαν`,
  ar = `Επεξεργασία: <1>Πίνακας ελέγχου αρχικής σελίδας δημιουργού</1>`,
  or = `Καλώς ορίσατε!`,
  sr = `<1>Τα παιχνίδια σας</1> – Τα παιχνίδια σας εμφανίζονται στη λίστα συνδεδεμένων εφαρμογών παρακάτω και είναι έτοιμα για χρήση. Απλώς προσθέστε και διαμορφώστε τις ενότητες παρακάτω, προκειμένου να διαθέσετε προς πώληση τα παιχνίδια, τα DLC, τα demo και τις μουσικές υποκρούσεις σας, με τρόπο που να ανταποκρίνεται καλύτερα στις ανάγκες σας.`,
  cr = `<1>Σύνδεση περισσότερων παιχνιδιών</1> – Εάν λείπουν παιχνίδια από την παρακάτω λίστα, αυτό σημαίνει ότι δεν τα έχετε συνδέσει με αυτήν την αρχική σελίδα δημιουργού. Για οδηγίες όσον αφορά τη σύνδεση παιχνιδιών με την αρχική σελίδα σας, ανατρέξτε στην τεκμηρίωση <2>Αρχικές σελίδες δημιουργού και εκδότη</2>.`,
  lr = `<1>Προεπιλεγμένη διάταξη</1> – Θα βρείτε παρακάτω ένα σύνολο προεπιλεγμένων ενοτήτων, που είναι ήδη διαμορφωμένες ώστε να αναδεικνύουν τις δημοφιλείς, τις προτεινόμενες και τις πρόσφατες κυκλοφορίες σας. Μπορείτε να χρησιμοποιήσετε όσα περισσότερα ή λιγότερα από τα προεπιλεγμένα στοιχεία, σύμφωνα με τις προτιμήσεις σας.`,
  ur = `Ανατρέξτε στην τεκμηρίωση για περισσότερες λεπτομέρειες`,
