  hr = `Αντιμετωπίσαμε ένα σφάλμα κατά τη διαδικασία προετοιμασίας δημοσίευσης: %1$s`,
  gr = `Η προσφορά αυτή έχει μια μεγάλη λίστα συνδεδεμένων αντικειμένων, επομένως οι ετικέτες των αντικειμένων της αναδημιουργούνται από το Κατάστημα. Αυτό μπορεί να διαρκέσει λίγη ώρα.`,
  _r = `Δεν ήταν δυνατή η αναδημιουργία των ετικετών των αντικειμένων αυτής της προσφοράς από το Κατάστημα, επομένως το εργαλείο επεξεργασίας δεν μπορεί να ανοίξει με ασφάλεια. Ανανεώστε τη σελίδα και δοκιμάστε ξανά.`,
  vr = `Για %1$s στοιχεία από τη λίστα συνδεδεμένων στοιχείων, δεν ήταν δυνατή η φόρτωση από το Κατάστημα, πιθανότατα επειδή έχουν αποκλειστεί ή διότι δεν διατίθενται πλέον προς πώληση. Οι ετικέτες τους δεν αναδημιουργήθηκαν, επομένως ίσως να μην εμφανίζονται σε ενότητες που φιλτράρονται βάσει ετικετών (μπορείτε να συνεχίσετε να εργάζεστε κανονικά αν έχουν αποκλειστεί κτλ.): %2$s. `,
