  Ir = `Λήξη σε συγκεκριμένη ώρα...`,
  Lr = `Εισαγάγετε ώρες στην τοπική ζώνη ώρα σας. Αυτές οι ώρες θα μετατραπούν αυτόματα και θα εμφανίζονται στην τοπική ώρα των παικτών.`,
  Rr = `Αυτόματες υπενθυμίσεις`,
  zr = `Ορίζοντας ένα συμβάν να ξεκινήσει στο μέλλον ΚΑΙ κάνοντας το ορατό στους ακόλουθούς σας νωρίτερα, σας επιτρέπει έπειτα να εγγραφείτε για ειδοποίηση όταν το συμβάν ξεκινήσει. Το Steam θα στείλει αυτόματα μια ειδοποίηση και/ή ένα email σε χρήστες Steam με βάση τις προτιμήσεις τους.`,
