  Sc = `Ολοκληρωμένο %1$s/%2$s`,
  Cc = `Προτεινόμενο`,
  wc = `Απαιτείται`,
  Tc = `Έγινε αίτημα`,
  Ec = `Περιγραφή`,
  Dc = `Τέχνη`,
