  Qg = `Λίστα επιτρεπόμενων μεταδοτών`,
  $g = `Αυτοί οι μεταδότες επιτρέπεται να εμφανίζονται στη σελίδα καταστήματος και συμβάντος σας όταν μεταδίδουν το παιχνίδι σας κατά τη διάρκεια αυτού του συμβάντος.`,
  e_ = `Προβολή πριν τη μετάδοση`,
