  I_ = `Προαιρετικό: Παρέχετε ένα συμβάν μετάδοσης που περιγράφει τις λεπτομέρειες των ρίψεων, χρήσιμο για συμβάντα εκπτώσεων που δεν συνθέτουν το σώμα συμβάντος τους.`,
