  R_ = `GID συμβάντος Clan`,
  z_ = `Εμφάνιση ευρείας αναπαραγωγής`,
  B_ = `Εάν οριστεί, η αριστερή και δεξιά στήλη δεν θα εμφανίζονται στο πρόγραμμα αναπαραγωγής. Αυτό είναι χρήσιμο μόνο όταν υπάρχει μία μετάδοση για το συμβάν και οι στήλες αποσπούν την προσοχή.`,
  V_ = `Ενεργοποίηση λειτουργίας ευρείας αναπαραγωγής`,
  H_ = `Αν επιτραπεί, εμφανίζεται το κουμπί εμφάνισης και απόκρυψης συνομιλίας. Όταν εμφανίζεται η συνομιλία, θα επιστρέφει στην κανονική, μη ευρεία λειτουργία παραθύρου αναπαραγωγής. Όταν η συνομιλία κλείνει, θα επιστρέφει στην ευρεία λειτουργία παραθύρου αναπαραγωγής.`,
