  G_ = `Εισαγωγή ID δωροπροσφοράς`,
  K_ = `Αν υπάρχει μια συσχετισμένη δωροπροσφορά με τη μετάδοση που ανακοινώνει νικητές μέσω της συνομιλίας μετάδοσης, τότε η ρύθμιση του GID της δωροπροσφοράς θα επιτρέπει την άντληση μηνυμάτων συνομιλίας, ακόμα και αν η συνομιλία είναι κλειστή, αναζητώντας ανακοινώσεις μόνο για σκοπούς προβολής.`,
