  ev = `Όταν είναι ενεργό, θα εμφανίζεται το μπάνερ στο Κατάστημα Steam αντί για τις κάψουλες παιχνιδιού. Αυτό είναι χρήσιμο όταν το μπάνερ επικοινωνεί πιο εφαρμοστές πληροφορίες για το συμβάν από συγκεκριμένες κάψουλες εφαρμογής. Επίσης, είναι χρήσιμο όταν πολλαπλά παιχνίδια μεταδίδονται με τον καιρό και θέλετε να δείξετε μόνο ένα μόνο στοιχείο συμβάντος.`,
