  Jy = `Αυτή θα είναι η προεπιλεγμένη εικόνα υπαναχώρησης αν δεν υπάρχει μια μεταφρασμένη έκδοση για μια γλώσσα που προσπαθεί να δει ένας χρήστης. Θα μπορούσε να είναι μια έκδοση χωρίς καμία γλώσσα μαρκαρισμένη ή θα μπορούσε να είναι μια συχνή γλώσσα για τους πελάτες σας.`,
