  _x = `Μπορείτε να ονομάσετε τα αρχεία εικόνας σας ώστε να λήγουν με ονόματα γλώσσας για να κατηγοριοποιηθούν αυτόματα ως αυτή τη γλώσσα (π.χ. «header_french.jpg»). %1$s για λίστα υποστηριζόμενων γλωσσών.`,
