  kx = `Μπορείτε να χρησιμοποιήσετε ολόκληρο τον χώρο της εικόνας και να συμπεριλάβετε τη δική σας περιγραφή για την ενημέρωση ή το συμβάν εντός της εικόνας σας.`,
  Ax = `Αυτή είναι μια έκδοση για κινητές συσκευές του παραπάνω Επίκεντρου Καταστήματος και χρησιμοποιείται όταν ένας χρήστης βλέπει το επίκεντρο από μια στενή οθόνη.`,
  jx = `Αυτή η εικόνα θα εμφανίζεται ως φόντο στη σελίδα προσφορών σας. Μπορείτε να τη συντάξετε ως μία μεγάλη εικόνα ή να δημιουργήσετε ένα πλακίδιο και να το ορίσετε ως επαναλαμβανόμενο μοτίβο.`,
  Mx = `Το σημαντικό περιεχόμενο θα πρέπει να τοποθετείται εντός των κεντρικών 940px της εικόνας σας. Το εικαστικό υλικό μπορεί επεκτείνεται στα πλάγια και προς τα κάτω, όπως επιθυμείτε. Γενικά, το εικαστικό υλικό πρέπει να διαβαθμίζεται προς ένα συμπαγές χρώμα στα πλάγια και στο κάτω μέρος και το χρώμα του φόντου πρέπει να είναι το ίδιο για να ταιριάζουν. Το μέγιστο μέγεθος εικόνας είναι 4MB.`,
  Nx = `Κάντε λήψη όλων των προτύπων της σελίδας προσφορών (αρχεία .psd)`,
