  Fx = `Πρότυπα`,
  Ix = `Αυτή η εικόνα θα επικαλύπτεται στο φόντο στην κορυφή της σελίδας σας. Αν θέλετε να έχετε μεταφράσεις για τις εικόνες, στείλτε ένα αρχείο .psd στην επαφή σας από τη Valve.`,
  Lx = `Εάν το παράσχετε, το μπάνερ αυτό θα εμφανίζεται στη σελίδα Καταστήματος για όλα τα παιχνίδια που συμμετέχουν σε αυτό το συμβάν προσφορών. Αυτό το μπάνερ παραμένει ορατό καθ' όλη τη διάρκεια του συμβάντος προσφορών, έως και δύο εβδομάδες. Λάβετε υπόψη ότι αυτό το μπάνερ πρέπει να εγκριθεί από τη Valve προτού χρησιμοποιηθεί και δεν μπορεί να περιέχει κίνηση.`,
