  Ux = `Απαιτείται`,
  Wx = `Προαιρετικό`,
  Gx = `Αυτή η εικόνα περιέχει συνήθως την τέχνη και τη μάρκα που αντιπροσωπεύει το συμβάν σας, συν οποιοδήποτε σύντομο μήνυμα θέλετε να δώσετε. Το Steam θα περιλαμβάνει αυτόματα το όνομα και το εικονίδιο του παιχνιδιού σας δίπλα από αυτή την εικόνα σε μερικά πλαίσια, αλλά μπορεί να θέλετε να συμπεριλάβετε το λογότυπο του παιχνιδιού σας στην εικόνα κάλυψης επίσης μιας και αυτή η εικόνα χρησιμοποιείται όταν το συμβάν σας κοινοποιείται σε κοινωνικά μέσα.`,
  Kx = `Θα εμφανιστεί στη σελίδα καταστήματος σας στις πρόσφατες ανακοινώσεις, σε λίστες συμβάντων και ανακοινώσεων και στη σελίδα λεπτομερειών της συλλογής σας. Αυτή η εικόνα θα χρησιμοποιηθεί για να εκπροσωπεύσει το συμβάν όταν μοιραστεί σε κοινωνικά μέσα. Χρησιμοποιείται για να συνδέσει το συμβάν/ανακοίνωσή σας και μπορεί να εμφανίζεται μαζί με περιεχόμενο από πολλά παιχνίδια, οπότε η εικόνα θα πρέπει να είναι καθαρή και αναγνωρίσιμη.`,
  qx = `Αυτή η εικόνα περιέχει συνήθως τα εικαστικά στοιχεία και την επωνυμία που αντιπροσωπεύει τον εκδότη, τον δημιουργό παιχνιδιών ή τη σειρά σας. Το Steam θα συμπεριλάβει αυτόματα το εικονίδιο του άβατάρ σας δίπλα από αυτήν την εικόνα, σε ορισμένα περιβάλλοντα.`,
  Jx = `Θα εμφανίζεται σε μέρη του Steam όπου προβάλλεται αυτή η αρχική σελίδα δημιουργού και θα χρησιμοποιείται ως αντιπροσωπευτική του συμβάντος, όταν κοινοποιείται σε μέσα κοινωνικής δικτύωσης. Η εικόνα πρέπει να είναι καθαρή και αναγνωρίσιμη.`,
