  Xx = `Εμφανίζεται στις ενότητες διασταυρούμενης προώθησης αυτού του συμβάντος προσφορών, όπως στη σελίδα «Εκπτώσεις και συμβάντα», στη θέση του λογότυπου της σελίδας προσφορών. Εάν αυτό το λογότυπο δεν χρειάζεται τοπική προσαρμογή, μεταφορτώστε το μία φορά, στα αγγλικά, και αυτό θα χρησιμοποιείται από όλες τις γλώσσες.`,
  Zx = `Ένα λογότυπο που εμφανίζεται στο πάνω μέρος της σελίδας προσφορών σας, πάνω από την εικόνα φόντου. Αυτή η εικόνα θα πρέπει να περιέχει το λογότυπο, τις ημερομηνίες και τυχόν σλόγκαν του συμβάντος σας και να έχει διαφανές φόντο.`,
  Qx = `Προβολή τεκμηρίωσης`,
