  YC = `Ειδοποίηση: Αυτό το συμβάν δεν έχει ενεργοποιημένο το χαρακτηριστικό Εκπτώσεων από τη Valve. Μόνο η Valve μπορεί να ενεργοποιήσει το χαρακτηριστικό εκπτώσεων στην κλειστή δοκιμαστική έκδοση. Επικοινωνήστε με την επαφή σας στη Valve για να αιτηθείτε να ενεργοποιήσει τη σελίδα εκπτώσεων για αυτό το συμβάν.`,
