  lT = `Αχρησιμοποίητα αντικείμενα: %1$s`,
  uT = `Αυτή είναι μία λίστα όλων των αντικειμένων που είναι συνδεδεμένα με την προσφορά και αυτήν τη στιγμή δεν τοποθετούνται εντός ΚΑΜΙΑΣ ενότητας, είτε ρητά είτε έχοντας συμπεριληφθεί μέσω ενός φίλτρου. Αυτό είναι χρήσιμο για να διασφαλίζεται ότι κάθε αντικείμενο είναι ορατό σε μία προσφορά και για να διερευνώνται οι ομαδοποιήσεις αχρησιμοποίητων αντικειμένων.`,
