  YD = `Προτάσεις και λίστες επιμελητή`,
  XD = `Ελέγχει πού εμφανίζονται οι προτάσεις επιμελητή ή η επιλεγμένη λίστα στη σελίδα. Από προεπιλογή, οι χρήστες που ακολουθούν επιμελητές Steam θα βλέπουν την πρόταση του επιμελητή που ακολουθούν για επιλεγμένα παιχνίδια στην προσφορά, στο κάτω μέρος της σελίδας. Αυτό σας επιτρέπει να ελέγχετε πού μπορεί να εμφανίζεται αυτή η ενότητα.`,
