  Tk = `Επιλέξτε μια καρτέλα εδώ για να εμφανίζονται μόνο στο εργαλείο επεξεργασίας οι ενότητες που είναι ορατές σε αυτήν την καρτέλα. Αυτό το χαρακτηριστικό είναι διαθέσιμο μόνο κατά τη διάρκεια της επεξεργασίας.`,
