  BR = `Αν θέλετε, μπορείτε να προσθέσετε BBCode, το οποίο θα εμφανίζεται μόνο αφού ο χρήστης απαντήσει σωστά όλες τις ερωτήσεις. Αυτή η ενότητα θα εμφανίζεται επίσης αμέσως μετά την τελευταία ερώτηση.`,
