  Kz = `Αλλαγή μεγέθους στοιχείου πλέγματος. Οι σειρές που περιέχουν 2 ή 3 στοιχεία πλέγματος επιτρέπουν την αύξηση των διαστάσεων ενός στοιχείου, μειώνοντας ανάλογα τα υπόλοιπα στοιχεία. Κάντε κλικ σε αυτό, για σμίκρυνση του στοιχείου πλέγματος.`,
