  eY = `Προαιρετικό κείμενο προς εμφάνιση στα δεξιά της τιμής όψης. Χρησιμοποιήστε το για να παρέχετε μια πολύ σύντομη εξήγηση της τιμής όψης. Για παράδειγμα, «1-2 ώρες» για μια τιμή όψης που ισχύει για παιχνίδια με σύντομο χρόνο παιχνιδιού.`,
  tY = `Όνομα αυτής της όψης. Μια όψη είναι ένα σύνολο από συσχετισμένες επιλογές, σε κάθε μία από τις οποίες μπορεί να κάνει κλικ ο χρήστης για να φιλτράρει τα παιχνίδια που εμφανίζονται σε αυτήν την ενότητα. Για παράδειγμα, «Είδος».`,
  nY = `Αυτόματη συμπλήρωση των όψεων και των τιμών όψεων βάσει των κατηγοριών ετικετών Καταστήματος, όπως «Είδος» και «Οπτικές ιδιότητες και οπτική γωνία». Μετά την αυτόματη δημιουργία, μπορείτε να επεξεργαστείτε κάθε όψη και κάθε τιμή όψης, όπου κρίνεται απαραίτητο.`,
