  lZ = `Επιλέξτε ένα ή περισσότερα αρχεία προς μεταφόρτωση για να εισαγάγετε τοπικοποιημένο κείμενο για τον τίτλο και το κύριο μέρος. Χρησιμοποιούμε την επέκταση του αρχείου για να καθορίσουμε εάν το αρχείο είναι εισαγωγή XML ή CSV. Για XML, χρησιμοποιούμε γλωσσικό κώδικα API στο τέλος του ονόματος του αρχείου, πριν την επέκταση, για να καθορίσουμε τη γλώσσα των περιεχομένων του αρχείου XML. Πρέπει να αρχίσετε κάνοντας εξαγωγή του CSV ή του XML, για να διασφαλίσετε ότι χρησιμοποιείτε τη σωστή μορφή.`,
